    "TORVE" to R.string.ui_text_3e178d57563f,
    "Torve is free software. There are no subscriptions or paid tiers." to R.string.ui_text_5c0be16d8014,
    "All product features are available without Google Play Billing, purchase restoration, premium status, or donor status. Account, privacy, device security, and backend availability checks may still apply." to R.string.ui_text_be4ca6c098e1,
