    "Search your watchlist" to R.string.ui_text_dfbde664bcef,
    "Tap the download icon on an episode to save it for offline access." to R.string.ui_text_14d5d8bb37d3,
    "Your Watchlist" to R.string.ui_text_5b213136c841,
    "Hidden Gems" to R.string.ui_text_2682957a1a48,
    "\r\n- Export supported account data in Settings > Account.\r\n- Delete your Torve account in the app, including from the subscription screen. Deleting an account does not delete records held independently by Apple or connected services.\r\n- Disconnect integrations and choose device-only storage where available.\r\n- Manage or cancel Apple billing in Apple's subscription settings.\r\n- Contact us about access, correction, deletion or other applicable privacy rights." to R.string.ui_text_1a30d9c613c8,
    "\r\nTorve is a media player. It does not host, store, or distribute any media content. \\\r\nUsers are responsible for ensuring they have legal access to any content they play.\r\n\r\nBy using this app, you agree to:\r\n- Use the app only with content you have the legal right to access\r\n- Not use the app for piracy or copyright infringement\r\n- Accept that the developers are not responsible for user content\r\n\r\nThis app connects to third-party services (debrid, Trakt, addons) at your discretion. \\\r\nYour API keys and credentials are stored locally on your device." to R.string.ui_text_81c24d220dcc,
    "\r\nWhen you use a Torve account, the service processes your email address, account identifier, password hash and authentication sessions. Account-backed features synchronize supported settings, favorites, watch history and playback progress. Device identifiers, names and connection information support synchronization and device management.\r\n\r\nCredentials selected for account storage are encrypted on Torve's servers and can be restored to signed-in devices. Device-only credentials remain on that device where this storage option is offered." to R.string.ui_text_20618c71dc38,
    " Press OK to manage." to R.string.ui_text_fdfe835cb2f7,
    " active filters" to R.string.ui_text_29e60e0b1e91,
    ". Nothing was removed." to R.string.ui_text_bbf2422a6968,
    "1–5 episodes" to R.string.ui_text_2eac442b1b10,
