@Composable
internal fun auditedUiText(value: String): String? {
    exactUiText[value]?.let { return stringResource(it) }
    uiTextPatterns.forEach { entry ->
        entry.arguments(value)?.let { return stringResource(entry.resource, *it) }
    }
    return null
}
